### src/hub.ts
import type { AuthorizationAccessType, AuthorizationRequest } from './types.js';

type ToolLike = {
  description?: string;
};

const DESTRUCTIVE_PATTERN = /\b(delete|destroy|purge|wipe|drop|archive|trash|remove|revoke|disconnect|deactivate)\b/i;
const WRITE_PATTERN = /\b(create|update|upsert|insert|append|send|post|publish|start|run|execute|sync|batch_update|values_update|set|assign|unassign|clear)\b/i;
const AUTH_ADMIN_PATTERN = /\b(get_connect_link|oauth|authorize|auth|token|consent|credential|scope)\b/i;
const CONTROL_PLANE_PATTERN = /\b(policy|rollout|registry|state|quota|rate_limit|discovery|bundle|trace)\b/i;

function joinedRouteText(route: {
  proxyToolName: string;
  serverName: string;
  downstreamToolName: string;
}, definition?: ToolLike): string {
  return [
    route.proxyToolName,
    route.serverName,
    route.downstreamToolName,
    definition?.description ?? '',
  ]
    .join(' ')
    .replace(/[_:/.-]+/g, ' ')
    .toLowerCase();
}

export function classifyHubRoute(route: {
  proxyToolName: string;
  serverName: string;
  downstreamToolName: string;
  serverTags?: string[] | null;
}, definition?: ToolLike): {
  accessType: AuthorizationAccessType;
  oauthRequired: boolean;
  tags: string[];
} {
  const text = joinedRouteText(route, definition);
  let accessType: AuthorizationAccessType = 'read';
  if (DESTRUCTIVE_PATTERN.test(text)) {
    accessType = 'destructive';
  } else if (CONTROL_PLANE_PATTERN.test(text)) {
    accessType = 'control_plane';
  } else if (AUTH_ADMIN_PATTERN.test(text)) {
    accessType = 'auth_admin';
  } else if (WRITE_PATTERN.test(text)) {
    accessType = 'write';
  }

  const oauthRequired =
    route.serverName.startsWith('composio-toolkit-') ||
    route.downstreamToolName.includes('oauth') ||
    route.downstreamToolName.includes('connect_link');

  const tags = [
    route.serverName,
    accessType,
    oauthRequired ? 'oauth_required' : 'oauth_not_required',
    ...((route.serverTags ?? []).filter((tag) => typeof tag === 'string' && tag.length > 0)),
  ];

  return { accessType, oauthRequired, tags: [...new Set(tags)] };
}

export function buildHubAuthorizationRequest(input: {
  accountId: string;
  tenantId?: string | null;
  userId?: string | null;
  sessionId?: string | null;
  role?: string | null;
  readOnly?: boolean;
  toolMode?: string | null;
  identitySource?: string | null;
  introspectionOk?: boolean;
  proxyToolName: string;
  serverName: string;
  downstreamToolName: string;
  serverTags?: string[] | null;
  actionName: 'discover' | 'execute';
  definition?: ToolLike;
  context?: Record<string, unknown>;
}): AuthorizationRequest {
  const classification = classifyHubRoute(
    {
      proxyToolName: input.proxyToolName,
      serverName: input.serverName,
      downstreamToolName: input.downstreamToolName,
      serverTags: input.serverTags ?? null,
    },
    input.definition,
  );

  return {
    actor: {
      accountId: input.accountId,
      tenantId: input.tenantId ?? null,
      userId: input.userId ?? null,
      sessionId: input.sessionId ?? null,
      role: input.role ?? null,
      readOnly: input.readOnly ?? input.toolMode === 'read_only',
      toolMode: input.toolMode ?? null,
      identitySource: input.identitySource ?? null,
    },
    action: {
      name: input.actionName,
      writeIntent: input.actionName === 'execute' && classification.accessType !== 'read',
      humanReviewStep: false,
      introspectionOk: input.introspectionOk ?? true,
    },
    resource: {
      kind: 'hub_route',
      id: input.proxyToolName,
      toolName: input.proxyToolName,
      serverName: input.serverName,
      downstreamToolName: input.downstreamToolName,
      accessType: classification.accessType,
      oauthRequired: classification.oauthRequired,
      tags: classification.tags,
      metadata: {
        description: input.definition?.description ?? null,
      },
    },
    context: input.context,
  };
}

### src/evaluate.ts
import {
  evaluateConstraintPolicyWithRollout,
  type HybridEvaluatorConfig,
  type RolloutConfig,
} from '@create-something/policy-os-engine';
import { getCompiledPolicy, getConstraintPolicy, getPolicyManifest } from './policies.js';
import type {
  AuthorizationDecision,
  AuthorizationEvaluationResult,
  AuthorizationRequest,
} from './types.js';

function normalizeToolMode(request: AuthorizationRequest): string | null {
  if (request.actor.toolMode) return request.actor.toolMode;
  if (request.actor.readOnly) return 'read_only';
  return null;
}

function toConstraintInput(request: AuthorizationRequest) {
  const entitlementSnapshot =
    request.context && typeof request.context.entitlementSnapshot === 'object' && request.context.entitlementSnapshot
      ? (request.context.entitlementSnapshot as Record<string, unknown>)
      : null;

  return {
    toolName:
      request.resource.toolName ??
      request.resource.downstreamToolName ??
      request.resource.id ??
      request.action.name,
    accountId: request.actor.accountId,
    readOnly: Boolean(request.actor.readOnly) || normalizeToolMode(request) === 'read_only',
    actionName: request.action.name,
    resourceKind: request.resource.kind,
    accessType: request.resource.accessType ?? undefined,
    oauthRequired: request.resource.oauthRequired,
    serviceTier:
      (typeof request.context?.serviceTier === 'string' ? request.context.serviceTier : undefined) ??
      (typeof entitlementSnapshot?.service_tier === 'string' ? entitlementSnapshot.service_tier : undefined),
    actorRole: request.actor.role ?? undefined,
    toolMode: normalizeToolMode(request) ?? undefined,
    identitySource: request.actor.identitySource ?? undefined,
    resourceTags: request.resource.tags ?? undefined,
    hasWriteIntent: request.action.writeIntent,
    hasHumanReviewStep: request.action.humanReviewStep,
    introspectionOk: request.action.introspectionOk,
    serviceEntitled:
      typeof entitlementSnapshot?.service_entitled === 'boolean' ? entitlementSnapshot.service_entitled : undefined,
    policyAccepted:
      typeof entitlementSnapshot?.policy_accepted === 'boolean' ? entitlementSnapshot.policy_accepted : undefined,
    contractActive:
      typeof entitlementSnapshot?.contract_active === 'boolean' ? entitlementSnapshot.contract_active : undefined,
    billingActive:
      typeof entitlementSnapshot?.billing_active === 'boolean' ? entitlementSnapshot.billing_active : undefined,
    approvedExceptionPresent:
      typeof entitlementSnapshot?.approved_exception === 'object' && entitlementSnapshot.approved_exception
        ? Boolean((entitlementSnapshot.approved_exception as Record<string, unknown>).present)
        : undefined,
  };
}

function toDecision(
  policyId: string,
  rollout: RolloutConfig,
  input: {
    decision: AuthorizationDecision['decision'];
    reason: string;
    matchedRuleIds: string[];
    policyHash?: string;
    compilerVersion?: string;
    evaluationPath: AuthorizationDecision['evaluationPath'];
    fallbackReason?: string | null;
    latencyMs: number;
  },
  sampledPolar: boolean,
  mismatch: boolean,
): AuthorizationDecision {
  return {
    decision: input.decision,
    reason: input.reason,
    matchedRuleIds: input.matchedRuleIds,
    policyId,
    policyHash: input.policyHash ?? null,
    compilerVersion: input.compilerVersion ?? null,
    evaluationPath: input.evaluationPath,
    fallbackReason: input.fallbackReason ?? null,
    latencyMs: Math.max(0, Math.floor(input.latencyMs)),
    rolloutMode: rollout.mode,
    canaryPercent: rollout.canaryPercent,
    sampledPolar,
    mismatch,
  };
}

export async function evaluateAuthorizationRequest(
  policyId: string,
  request: AuthorizationRequest,
  rollout: RolloutConfig,
  config: HybridEvaluatorConfig,
): Promise<AuthorizationEvaluationResult> {
  const manifest = getPolicyManifest(policyId);
  const policy = getConstraintPolicy(policyId);
  const compiled = getCompiledPolicy(policyId);
  const result = await evaluateConstraintPolicyWithRollout(
    toConstraintInput(request),
    policy,
    rollout,
    config,
  );

  return {
    final: toDecision(policyId, rollout, result.final, result.sampledPolar, result.mismatch),
    legacy: toDecision(policyId, rollout, result.legacy, false, result.mismatch),
    polar: toDecision(policyId, rollout, result.polar, true, result.mismatch),
    manifest,
    policy,
    compiled,
    request,
  };
}

export function blockedByPolicy(decision: AuthorizationDecision): string | null {
  return decision.decision === 'block' ? decision.policyId : null;
}

export function requiresHumanReview(decision: AuthorizationDecision): boolean {
  return decision.decision === 'require_human_review';
}

